# ---------------------------------------------------------------------------
# Telescope lookup helpers
# ---------------------------------------------------------------------------

def normalize_telescope_name(raw_name: str) -> str:
    """Normalize a telescope name from FITS header for database lookup."""
    if not raw_name:
        return ''
    
    name = raw_name.strip()
    name_upper = name.upper()
    
    # Try direct mapping first
    if name_upper in TELESCOPE_HEADER_MAPPING:
        return TELESCOPE_HEADER_MAPPING[name_upper]
    
    # Try case-insensitive search
    for key, canonical in TELESCOPE_HEADER_MAPPING.items():
        if key.upper() == name_upper:
            return canonical
    
    # Try partial matches on database keys
    for db_key in TELESCOPES_DATABASE:
        if db_key == 'default':
            continue
        if db_key.upper() in name_upper or name_upper in db_key.upper():
            return db_key
    
    return name


def lookup_telescope(raw_name: str) -> Optional[Dict[str, Any]]:
    """
    Look up telescope specs from a FITS header telescope name.
    Returns dict with diameter_mm, focal_length_mm, f_number.
    """
    canonical = normalize_telescope_name(raw_name)
    
    if canonical in TELESCOPES_DATABASE:
        return TELESCOPES_DATABASE[canonical]
    
    # Fuzzy case-insensitive
    for key, specs in TELESCOPES_DATABASE.items():
        if key.upper() == canonical.upper():
            return specs
    
    return None


def get_focal_length(raw_name: str) -> Optional[float]:
    """Get focal length in mm for a telescope."""
    specs = lookup_telescope(raw_name)
    return specs['focal_length_mm'] if specs else None


def get_aperture(raw_name: str) -> Optional[float]:
    """Get aperture diameter in mm for a telescope."""
    specs = lookup_telescope(raw_name)
    return specs['diameter_mm'] if specs else None


def get_focal_ratio(raw_name: str) -> Optional[float]:
    """Get focal ratio (f/number) for a telescope."""
    specs = lookup_telescope(raw_name)
    return specs['f_number'] if specs else None


def calculate_image_scale(telescope_name: str, camera_name: str) -> Optional[float]:
    """
    Calculate image scale in arcsec/pixel.
    Formula: scale = 206.265 * pixel_size_um / focal_length_mm
    """
    from .cameras import get_pixel_size
    
    focal = get_focal_length(telescope_name)
    pixel = get_pixel_size(camera_name)
    
    if focal and pixel and focal > 0:
        return 206.265 * pixel / focal
    return None


def calculate_fov(telescope_name: str, camera_name: str) -> Optional[tuple]:
    """
    Calculate field of view in arcminutes (width, height).
    """
    from .cameras import get_sensor_dimensions, get_pixel_size
    
    focal = get_focal_length(telescope_name)
    pixel = get_pixel_size(camera_name)
    dims = get_sensor_dimensions(camera_name)
    
    if not (focal and pixel and dims and focal > 0):
        return None
    
    scale = 206.265 * pixel / focal  # arcsec/pixel
    w_arcmin = (dims[0] * scale) / 60.0
    h_arcmin = (dims[1] * scale) / 60.0
    
    return (round(w_arcmin, 1), round(h_arcmin, 1))


def detect_focal_reducer(declared_focal: float, actual_focal: float,
                         tolerance: float = 0.05) -> Optional[float]:
    """
    Detect if a focal reducer is in use by comparing declared vs actual focal length.
    Returns the reducer factor (e.g., 0.73) or None if no reducer detected.
    
    Args:
        declared_focal: Focal length from telescope database (mm)
        actual_focal: Focal length from plate solving (mm)
        tolerance: How close to 1.0 before we consider no reducer
    """
    if declared_focal <= 0 or actual_focal <= 0:
        return None
    
    ratio = actual_focal / declared_focal
    
    # If ratio is close to 1.0, no reducer
    if abs(ratio - 1.0) < tolerance:
        return None
    
    # Common reducer factors: 0.63, 0.67, 0.72, 0.73, 0.76, 0.8, 0.85
    return round(ratio, 3)


# ---------------------------------------------------------------------------
# Telescope merging / aliasing (user-defined grouping)
# ---------------------------------------------------------------------------

# User-defined aliases: maps variant names to canonical name
# Loaded from config at startup, editable via UI
_TELESCOPE_ALIASES: Dict[str, str] = {}


def set_telescope_aliases(aliases: Dict[str, str]):
    """Set user-defined telescope aliases (variant -> canonical)."""
    global _TELESCOPE_ALIASES
    _TELESCOPE_ALIASES = {k.upper(): v for k, v in aliases.items()}


def get_telescope_aliases() -> Dict[str, str]:
    """Get current telescope aliases."""
    return dict(_TELESCOPE_ALIASES)


def add_telescope_alias(variant_name: str, canonical_name: str):
    """Add a single telescope alias."""
    _TELESCOPE_ALIASES[variant_name.upper()] = canonical_name
    _save_aliases_to_config()


def remove_telescope_alias(variant_name: str):
    """Remove a telescope alias."""
    _TELESCOPE_ALIASES.pop(variant_name.upper(), None)
    _save_aliases_to_config()


def _save_aliases_to_config():
    """Persist telescope aliases to config."""
    try:
        from core.config import get_config
        config = get_config()
        config.set('telescope_aliases', dict(_TELESCOPE_ALIASES))
        config.save_config()
    except Exception:
        pass


def _load_aliases_from_config():
    """Load telescope aliases from config."""
    global _TELESCOPE_ALIASES
    try:
        from core.config import get_config
        config = get_config()
        aliases = config.get('telescope_aliases', {})
        if isinstance(aliases, dict):
            _TELESCOPE_ALIASES = {k.upper(): v for k, v in aliases.items()}
    except Exception:
        pass


# Load aliases on import
try:
    _load_aliases_from_config()
except Exception:
    pass


def resolve_telescope_name(raw_name: str) -> str:
    """
    Resolve a telescope name using both built-in normalization and user aliases.
    This is the main function to use for telescope identification.
    Returns the canonical name.
    """
    if not raw_name:
        return ''

    # Check user aliases first
    upper = raw_name.strip().upper()
    if upper in _TELESCOPE_ALIASES:
        return _TELESCOPE_ALIASES[upper]

    # Then use built-in normalization
    return normalize_telescope_name(raw_name)


def find_similar_telescopes(telescope_names: list) -> list:
    """
    Find groups of telescope names that likely refer to the same instrument.
    Returns list of groups: [['name1', 'name2', ...], ...]
    Useful for suggesting merge candidates to the user.
    """
    import re
    groups = []
    processed = set()

    # Normalize all names for comparison
    def _simplify(name):
        s = re.sub(r'[^A-Z0-9]', '', name.upper())
        return s

    names = list(set(telescope_names))
    simplified = {n: _simplify(n) for n in names}

    for i, name1 in enumerate(names):
        if name1 in processed:
            continue
        group = [name1]
        s1 = simplified[name1]

        for j, name2 in enumerate(names):
            if j <= i or name2 in processed:
                continue
            s2 = simplified[name2]

            # Check if one contains the other, or differ only by separators
            if s1 == s2 or s1 in s2 or s2 in s1:
                group.append(name2)
                continue

            # Check if they resolve to same database entry
            specs1 = lookup_telescope(name1)
            specs2 = lookup_telescope(name2)
            if specs1 and specs2 and specs1 == specs2:
                group.append(name2)

        if len(group) > 1:
            for n in group:
                processed.add(n)
            groups.append(group)

    return groups


def list_telescopes_by_brand() -> Dict[str, list]:
    """Return telescopes organized by brand."""
    brands = {}
    brand_prefixes = {
        'FC': 'Takahashi', 'TSA': 'Takahashi', 'TOA': 'Takahashi', 'FSQ': 'Takahashi',
        'Epsilon': 'Takahashi', 'Mewlon': 'Takahashi', 'BRT': 'Takahashi', 'CN': 'Takahashi',
        'CPC': 'Celestron', 'C5': 'Celestron', 'C6': 'Celestron', 'C8': 'Celestron',
        'C9': 'Celestron', 'C11': 'Celestron', 'C14': 'Celestron', 'RASA': 'Celestron',
        'EdgeHD': 'Celestron', 'NexStar': 'Celestron', 'CGX': 'Celestron',
        'SW': 'Sky-Watcher', 'HEQ': 'Sky-Watcher', 'EQ': 'Sky-Watcher',
        'Evostar': 'Sky-Watcher', 'Esprit': 'Sky-Watcher', 'Explorer': 'Sky-Watcher',
        'Quattro': 'Sky-Watcher', 'Heritage': 'Sky-Watcher', 'Dobson': 'Sky-Watcher',
        'Meade': 'Meade', 'LX': 'Meade', 'ACF': 'Meade',
        'WO': 'William Optics', 'ZenithStar': 'William Optics', 'GT': 'William Optics',
        'RedCat': 'William Optics', 'SpaceCat': 'William Optics',
        'Vixen': 'Vixen', 'VSD': 'Vixen',
        'APM': 'APM', 'TEC': 'TEC', 'Stellarvue': 'Stellarvue',
        'ES': 'Explore Scientific', 'ASA': 'ASA', 'CDK': 'Planewave',
        'RC': 'Planewave/GSO',
        'iTelescope': 'iTelescope', 'T': 'iTelescope',
    }
    
    for key in sorted(TELESCOPES_DATABASE.keys()):
        if key == 'default':
            continue
        
        brand = 'Other'
        for prefix, b in brand_prefixes.items():
            if key.startswith(prefix):
                brand = b
                break
        
        if brand not in brands:
            brands[brand] = []
        brands[brand].append(key)
    
    return brands
